NUM = '205-013'
TITLE = 'Resin Elution Efficiency and Barren Resin Loading Test'
NEW_TITLE = TITLE
NEW_JSEA = 'JSEA-PRO-MET-' + NUM
HAZARDS = [h.replace('cloth gloves worn', 'chemical-resistant gloves worn') for h in hazards_from(os.environ['SRC_DOCX'])]
PPE = PPE_LAB_ACID
DESC = desc205(['Measure how completely the elution circuit strips the resin, at the bench.', 'Barren resin loading is to the resin circuit what barren carbon is to the CIL circuit.', 'The bench methods come from the Martabe resin testwork - preconditioning, copper elution, NaCl comparison, eluant scale dissolution, NaCN-NaCl mixing, copper loading by Zn(CN)4 elution, and the dosing pump calibration they use.'], 'To be set once the vendor data arrives.', NUM, True, extra_bold=['Draft for review - NOT FOR USE until approved. Steps 2 to 10 follow the Martabe work instructions Testing NaCl from New Vendor (11/01/2025), Preconditioning Resin with Cu Variance V2 (07/02/2025), Testwork Pelarutan Scaling Eluant Garam Menggunakan Sulfamic Acid (07/10/2025), IPHK Mixing Larutan Campuran NaCN-NaCl (undated), Copper Loading Test (DOC-3-MET-MEL-WIN-00113-IE, 25/01/2025) and Dosing Pump Grundfos DDA Calibration (DOC-3-MET-PMC-WIN-00120-IE, 25/12/2024). Preconditioning follows V2. Every cyanide addition is made at pH 10.5 or above. JSEA-PRO-MET-205-013 must be updated for the added hazards before this instruction is approved.', 'Open items: (1) acceptance targets need Goldquip resin elution data, not received; (2) the NaCN to CuSO4 ratio differs between the NaCl vendor method and V2 (about 0.107 against 0.15 g/mL), and the CuSO4 solution strength and hydrate are not stated; (3) confirm the eluant strength of 29.4 g NaCN in 600 mL (about 49 g/L); (4) confirm which NaCl sources the four resin charges represent; (5) confirm the plant NaCl and NaCN solution strengths for the mixing test, and what IPHK stands for; (6) the source adds the KCN solution to the zinc sulphate solution, which is slightly acidic - confirm the order with HSE; adding the zinc sulphate to the alkaline KCN keeps the cyanide alkaline; (7) confirm the Mt. Morgan cyanide-bearing route for the hi-cyanide eluate - the Martabe tailing sump pump is a source name; (8) confirm the dosing pump hose connections against the pump manual; (9) confirm the Mt. Morgan worksheets for the elution, copper loading and pump calibration records - the Martabe G: drive files and forms are source names.'], points=('Met lab bench - physical testwork bench and instrument',))
STEPS = [
    ('Pre-start Check', PRESTART_LAB_HAZ, prestart_lab(NEW_JSEA, [LAB_ALONE] + ['Do all cyanide work in this instruction inside the fume cupboard.', 'Confirm no acid is in the fume cupboard or the work area while any cyanide solution is open.', 'Take 5 and prepare the equipment, reagents and sample bottles for the test. Check the equipment is in good condition and every reagent is in date.']), None, ['Bench elution columns 150 mL and 300 mL, Grundfos DDA dosing pump, quick-connect hose and fittings', 'Baffle tank with agitator or magnetic stirrer', 'Balance, beakers 150 and 500 mL, measuring cylinders, sample bottles labelled hi cyanide', 'pH meter, stopwatch, filter paper, plastic bag for resin sampling', 'Fresh and loaded resin samples', 'NaCN, KCN, CuSO4, caustic (solid and solution), NaCl (plant and vendor), zinc sulphate heptahydrate', 'AgNO3 0.1 M and 0.01 M', 'Sulfamic acid, eluant salt scale sample, raw and process water', 'Eluant solutions and heating'] + [PPE_EQ]),
    ('Preconditioning - Copper Loading on Fresh Resin', ['Solid NaCN handling', 'HCN below pH 10.5', 'Copper-cyanide solution'], ['Put 4 L distilled water in the baffle tank. Adjust and hold the pH at 10.5 to 12 with caustic.', 'Dose for the copper level under test (V2, 300 mL resin): 70 kg/t = 20.42 g NaCN and 136.4 mL CuSO4 solution; 100 kg/t = 29.17 g and 194.9 mL; 125 kg/t = 36.46 g and 243.6 mL. Add the NaCN and mix, then the CuSO4, keeping the pH at 10.5 to 12.', 'Sample 100 mL and record the final pH. Titrate with AgNO3 0.01 M and send the remainder for Cu assay as the head.', 'Put 300 mL of fresh resin in the column and inject the solution for 1 hour at 1 L/h. Flush the column with 200 mL distilled water.', 'Record the final product volume, stir, and sample 100 mL as the precondition tail. Titrate with AgNO3 0.01 M and send the remainder for Cu assay.', 'Split the resin - 150 mL for the elution or copper loading test and 150 mL for Cu assay by AAS. For the NaCl comparison prepare four preconditioned resins (see Open items).'], 'CAUTION: Raise the pH to 10.5 or above BEFORE any cyanide is added.', None),
    ('Copper Elution Test - Eluant', ['Concentrated NaCN eluant', 'HCN below pH 10.5'], ['Weigh 29.4 g NaCN (see Open items) and 36.2 g NaCl - plant or vendor sample under test.', 'Put 300 mL distilled water in a beaker, add the NaCl and stir.', 'Adjust to pH 10.5 to 11 with NaOH. Confirm the pH is 10.5 or above before the NaCN is added.', 'Add the NaCN and stir. Make up to 600 mL with distilled water and stir.'], 'CAUTION: Concentrated cyanide eluant. Fume cupboard, personal HCN monitor on, not alone.', None),
    ('Copper Elution Test - Column Run', ['Cyanide-bearing eluate', 'Pinch point at the hose'], ['Fill the column with 150 mL of preconditioned resin with no voids between resin.', 'Fill the column with distilled water, calibrate the pump (Step 10), then drain the remaining water from the column.', 'Run the eluant with the dosing pump at 1 BV/h (150 mL/h, 2.5 mL/min) for 3 hours. Target final elution volume 450 mL; the 150 mL left in the beaker goes to the cyanide-bearing waste.', 'Direct the eluate to a beaker. Use 2 measuring cylinders alternately to move the eluate to the sample bottles.', 'Sample the eluate at 30, 60, 90, 120, 150 and 180 minutes, about 75 mL per 30 minutes, into labelled bottles.', 'Titrate every sample for cyanide as SWI-PRO-MET-205-001 - AgNO3 0.1 M for the concentrated eluate, 0.01 M for dilute solutions. Send the samples for Cu and Fe assay and record the results on the copper elution worksheet.'], None, None),
    ('NaCl Dissolution Test', ['Salt dust', 'Precipitate not recorded'], ['Dissolve the NaCl of each vendor and the plant NaCl into 500 mL of solution: 1 M = 30.15 g and 3 M = 90.46 g per 500 mL (97 per cent purity, 58.5 g/mol).', 'Run a jar test for 50 minutes.', 'Observe and photograph any precipitate.'], None, None),
    ('Eluant Scale Dissolution with Sulfamic Acid', ['HCN when acid contacts cyanide-bearing scale', 'Sulfamic acid contact', 'Test left unattended'], ['Make the sulfamic acid solutions: 7.5 g sulfamic acid in 300 mL process water (test 1) and in 300 mL raw water (test 2). Mix with the magnetic stirrer.', 'Weigh 5 g of scale sample. Put it into the sulfamic acid solution inside the fume cupboard, WITHOUT stirring.', 'Observe and photograph at minute 0, 5, 10, 30, 60, 120 and 240 while any deposit remains. Stay with the test for the full 240 minutes with the personal HCN monitor on.', 'If HCN above 5 ppm is detected, stop: dilute the solution with water and evacuate.', 'Send the solution and residue to the cyanide-bearing stream until the scale is shown to be cyanide-free.'], 'CAUTION: Acid on cyanide-bearing scale releases HCN. Fume cupboard only, attended for the full test, stop at 5 ppm.', None),
    ('NaCN-NaCl Mixing Test', ['Toxic mixed solution splash', 'HCN below pH 10.5'], ['Work in the fume cupboard with clean, dry equipment.', 'Measure 85 mL of plant NaCl solution into a 150 mL beaker. Raise its pH to 10.5 or above with caustic before any NaCN is added.', 'Add 15 mL of plant NaCN solution slowly to the NaCl solution, stirring gently at low speed. Always add the NaCN to the NaCl, never the reverse, to avoid splashing toxic solution.', 'Check the total is about 100 mL (target 1.0 M NaCN and 0.9 M NaCl), homogenise for about 1 minute, and observe for any precipitate or colour change.', "Store in a tightly closed container labelled 'NaCN-NaCl Mix, Toxic'."], None, None),
    ('Copper Loading Test - Zn(CN)4 Eluant', ['Bulk hi-cyanide eluant (351 g KCN)', 'HCN below pH 10.5', 'Resin sampling at the loaded resin screen'], ['Take the loaded resin sample at the loaded resin screen in a plastic bag as it discharges, as SWI-PRO-MET-201-012.', 'Weigh 322.8 g zinc sulphate heptahydrate and 351 g KCN.', 'Add solid caustic slowly to 800 mL distilled water until the pH is 10.5 or above. The Martabe pH 10 is not used.', 'Add the KCN slowly and mix until clear. Monitor the pH at every step and hold it at 10.5 to 11 with NaOH.', 'Dissolve the zinc sulphate in 1000 mL distilled water in a separate container and wait about 30 minutes until clear.', 'Combine the two solutions watching the pH at all times - stop if it falls below 10.5 (see Open items for the order). Make up to 2.2 L with distilled water and mix until clear.'], 'CAUTION: 351 g KCN. Fume cupboard, HCN monitor on, no acid in the work area, not alone and not unattended.', None),
    ('Copper Loading Test - Column Elution', ['Pinch point at the quick-connect', 'Hi-cyanide eluate'], ['Wash the loaded resin on a sieve with water. Fill the 150 mL column with 150 mL of resin with no voids.', 'Connect the pump to the bottom inlet with the quick-connect hose; the eluate leaves at the top through a hose into a beaker. Keep hands clear of the pinch point.', 'Inject distilled water to remove voids, calibrate the dosing pump (Step 10) and drain the remaining water.', 'Run the Zn(CN)4 eluant at 2 BV/h (300 mL/h) for 6 hours with no water or air in the hose.', "Collect the eluate every hour, hour 0 to 6, into bottles labelled 'hi cyanide' and send for Cu, Fe and Zn assay.", 'Drain the column into a sample bottle and record the volume. Rinse the resin in 300 mL water for 15 minutes. Send both for Cu, Fe and Zn.', 'Send the waste liquid to the cyanide-bearing stream (see Open items) and return the resin to the loaded resin at the ReCYN plant. Record the copper loading calculation and assays.'], None, None),
    ('Dosing Pump Calibration - Grundfos DDA', ['Pump calibrated on water only', 'Air in the hose'], ['Prepare the dosing pump, measuring cylinder, hoses and fittings, and water. Check they are in good condition.', 'Press the 100% button. Make sure there are no air gaps in the hose.', "Press '>' for the setup screen, turn the dial to 'calibration', press the dial, then click start.", 'Collect the water the pump draws in the measuring cylinder (see Open items for the hose connections).', 'Compare the cylinder volume with the panel volume. If they differ, set the panel volume to the measured value, click start, then OK. Repeat from the start if still different.', 'Check the delivered flow at the test rate - 150 mL/h for Step 4, 300 mL/h for Step 9. Record the calibration in the pump calibration logsheet.'], None, None),
    CLOSE_LAB_STEP,
]
